def _match(self, mask, item):
        # checks if item is covered by the mask
        if '*' not in mask:
            return item == mask
        elif mask == '*/*':
            return True
        else:
            assert mask.endswith('/*')
            mask_major = mask[:-2]
            item_major = item.split('/', 1)[0]
            assert item_major != '*', "item must be a specific type"
            return item_major == mask_major

